import Foundation
import Testing
@testable import PersonaKit

struct DocumentCompareTests {
    private typealias U = DocumentText.Unit

    @Test func changesUnderTheirUnitWithTheRestFolded() {
        let old = [U(label: "第 1 页", lines: (1...10).map { "行 \($0)" }), U(label: "第 2 页", lines: ["甲", "乙"])]
        var newLines = (1...10).map { "行 \($0)" }
        newLines[5] = "行 6（改了）"
        let new = [U(label: "第 1 页", lines: newLines), U(label: "第 2 页", lines: ["甲", "乙", "丙"])]
        let r = TextCompare.compare(old, new)
        #expect(r.added == 2 && r.removed == 1)
        #expect(r.rows.first == .folded(3))
        #expect(r.rows.contains(.unit("第 1 页")) && r.rows.contains(.unit("第 2 页")))
        #expect(r.rows.contains(.removed("行 6")) && r.rows.contains(.added("行 6（改了）")) && r.rows.contains(.added("丙")))
        #expect(r.rows.contains(.same("行 5")) && !r.rows.contains(.same("行 1")))
    }

    @Test func sameTextIsNoRows() {
        let u = [U(label: "第 1 页", lines: ["a", "b"])]
        #expect(TextCompare.compare(u, u).rows.isEmpty)
        #expect(TextCompare.compare([], u).added == 2) // a new file
    }

    @Test func kinds() {
        #expect(DocumentText.kind("a.DOCX") == .docx && DocumentText.kind("b.pptx") == .pptx && DocumentText.kind("c.xlsx") == .xlsx)
        #expect(DocumentText.kind("d.pdf") == .pdf && DocumentText.kind("e.png") == .image && DocumentText.kind("f.swift") == nil)
    }

    @Test func wordAndSlides() throws {
        // `swift test` has no app catalog, so a label comes back as its English development key ("Page 1").
        let docx = try DocumentText.units(Data(base64Encoded: "")!, kind: .docx)
        #expect(docx == [U(label: "Page 1", lines: ["标题", "第一段", "• 要点", "第二段"])])
        let pptx = try DocumentText.units(Data(base64Encoded: "")!, kind: .pptx)
        #expect(pptx == [U(label: "Slide 1", lines: ["第一张", "甲", "乙"]), U(label: "Slide 2", lines: ["第二张", "丙"])])
    }
}
